import {formatResult} from './board-model.mjs';
export const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
export function safePortrait(url){if(/^assets\/people\/[a-z0-9-]+\.jpg$/.test(url))return url;try{const value=new URL(url);return value.protocol==='https:'&&!value.username&&!value.password?value.href:null;}catch{return null;}}
function memberSocial(record){return record.sample&&/^@[a-z0-9._]{1,30}$/i.test(record.instagramAlias||'')?`<div class="profile-social profile-social-alias"><span>${escapeHtml(record.instagramAlias)}</span><small>Placeholder handle</small></div>`:'';}
export function renderRecord(record,definition){
 const portrait=safePortrait(record.portraitUrl);return `<article class="record-row">${portrait?`<img src="${escapeHtml(portrait)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:'<span class="record-symbol" aria-hidden="true">↗</span>'}<div><h4>${escapeHtml(record.memberName)}</h4><p>${escapeHtml(new Date(record.achievedOn+'T12:00:00Z').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Kolkata'}))}${record.sample?' · Illustrative record':''}</p>${memberSocial(record)}</div><strong>${escapeHtml(formatResult(record,definition))}</strong></article>`;
}
export function renderSpotlights(groups){
 const seen=new Set(),featured=[];
 for(const group of groups)for(const record of group.leaders){if(seen.has(record.memberName)||!safePortrait(record.portraitUrl))continue;seen.add(record.memberName);featured.push({record,definition:group.definition});if(featured.length===3)break;}
 return featured.slice(0,3).map(({record,definition})=>`<article class="board-spotlight"><div class="spotlight-photo"><img src="${escapeHtml(safePortrait(record.portraitUrl))}" alt="${record.sample?'AI-generated fictional portrait for sample member ':'Portrait of '}${escapeHtml(record.memberName)}" loading="lazy">${record.sample?'<span class="portrait-label">AI sample portrait</span>':''}<div class="spotlight-result"><span>${escapeHtml(definition.label)}</span><strong>${escapeHtml(formatResult(record,definition))}</strong></div></div><div class="spotlight-caption"><h3>${escapeHtml(record.memberName)}</h3><p>${record.sample?'Illustrative record holder':escapeHtml(record.divisionId)}</p>${memberSocial(record)}</div></article>`).join('');
}
export function renderStatus(state){return ({unconfigured:'<div class="board-empty"><span aria-hidden="true">—</span><h3>The next standard is yours to set.</h3><p>The Board is not yet open for published records. Speak to a coach about an attempt.</p></div>',error:'<div class="board-empty"><h3>Records couldn’t load.</h3><p>Please retry in a moment.</p><button class="button blue" data-board-retry>Retry ↗</button></div>',empty:'<div class="board-empty"><span aria-hidden="true">—</span><h3>No approved records yet.</h3><p>Every record starts with an attempt. Speak to a coach about yours.</p></div>'})[state]||'';}
